  const v8df x0r = *(const v8df*)(pr + 0);
  const v8df x0i = *(const v8df*)(pi + 0);
  const v8df x1r = *(const v8df*)(pr + 8);
  const v8df x1i = *(const v8df*)(pi + 8);
  const v8df x2r = *(const v8df*)(pr + 16);
