      a13_emitmc_w8(A13_xr, A13_xi, A13_cr, A13_ci, outm + b*(long)4394);
      break;
    case 4:
      a13_conv_in_w4(xs, A13_xr, A13_xi);
      a13_conv_in_w4(cs, A13_cr, A13_ci);
      a13_stepf_w4(A13_xr, A13_xi);
