      a13_emitmc_w2(A13_xr, A13_xi, A13_cr, A13_ci, outm + b*(long)4394);
      break;
    case 1:
      a13_conv_in_w1(xs, A13_xr, A13_xi);
      a13_conv_in_w1(cs, A13_cr, A13_ci);
      a13_stepf_w1(A13_xr, A13_xi);
      a13_emitmc_w1(A13_xr, A13_xi, A13_cr, A13_ci, out1 + b*(long)4394);
