static void b36_conv_in(const double*restrict src, double*restrict dx, double padval){
  for(long j0=0;j0<36;++j0){
    for(long j1=0;j1<36;++j1){
      const double* s = src + (j0*36+j1)*72;
      double* pr = dx + j0*2888 + pos36[j1]*80;
      double* pi = pr + 40;
      for(long z=36;z<36;++z){ pr[z]=padval; pi[z]=0.0; }
      for(long z=0;z<36;++z){ pr[pos36[z]]=s[2*z]; pi[pos36[z]]=s[2*z+1]; }
    }
    for(long j1=36;j1<36;++j1){
      double* pr = dx + j0*2888 + j1*80;
      double* pi = pr + 40;
      for(long z=0;z<36;++z){ pr[z]=padval; pi[z]=0.0; }
    }
  }
}
static void b36_emit(const double*restrict dx, double*restrict dst){
  for(long j0=0;j0<36;++j0) for(long j1=0;j1<36;++j1){
    double* s = dst + (j0*36+j1)*72;
    const double* pr = dx + j0*2888 + pos36[j1]*80;
    const double* pi = pr + 40;
    for(long z=0;z<36;++z){ s[2*z]=pr[pos36[z]]; s[2*z+1]=pi[pos36[z]]; }
  }
}

