static void b45_init(void){ if(!B45_x){
  size_t n = (size_t)45*4616+64;
  B45_x=xalloc(n*8); B45_c=xalloc(n*8); B45_xb=xalloc(n*8); B45_cb=xalloc(n*8);
  size_t t = (size_t)48*96+64; B45_t=xalloc(t*8); B45_t2=xalloc(t*8); } }

static void b45_conv_in(const double*restrict src, double*restrict dx, double padval){
  for(long j0=0;j0<45;++j0){
    for(long j1=0;j1<45;++j1){
      const double* s = src + (j0*45+j1)*90;
      double* pr = dx + j0*4616 + pos45[j1]*96;
      double* pi = pr + 48;
      for(long z=45;z<48;++z){ pr[z]=padval; pi[z]=0.0; }
      for(long z=0;z<45;++z){ pr[pos45[z]]=s[2*z]; pi[pos45[z]]=s[2*z+1]; }
    }
    for(long j1=45;j1<48;++j1){
      double* pr = dx + j0*4616 + j1*96;
      double* pi = pr + 48;
      for(long z=0;z<48;++z){ pr[z]=padval; pi[z]=0.0; }
    }
  }
}
static void b45_emit(const double*restrict dx, double*restrict dst){
  for(long j0=0;j0<45;++j0) for(long j1=0;j1<45;++j1){
    double* s = dst + (j0*45+j1)*90;
    const double* pr = dx + j0*4616 + pos45[j1]*96;
    const double* pi = pr + 48;
    for(long z=0;z<45;++z){ s[2*z]=pr[pos45[z]]; s[2*z+1]=pi[pos45[z]]; }
  }
}

static void b45_t1_plane(double*restrict br, double*restrict tr){
    b45_t_w8(br + 0, br + 0 + 48, tr + 0*96, tr + 0*96 + 48);
    b45_t_w8(br + 8, br + 8 + 48, tr + 8*96, tr + 8*96 + 48);
    b45_t_w8(br + 16, br + 16 + 48, tr + 16*96, tr + 16*96 + 48);
    b45_t_w8(br + 24, br + 24 + 48, tr + 24*96, tr + 24*96 + 48);
    b45_t_w8(br + 32, br + 32 + 48, tr + 32*96, tr + 32*96 + 48);
    b45_t_w8(br + 40, br + 40 + 48, tr + 40*96, tr + 40*96 + 48);
}
static void b45_t1m_plane(double*restrict br, const double*restrict kr, double*restrict tr){
    b45_tm_w8(br + 0, br + 0 + 48, kr + 0, kr + 0 + 48, tr + 0*96, tr + 0*96 + 48);
    b45_tm_w8(br + 8, br + 8 + 48, kr + 8, kr + 8 + 48, tr + 8*96, tr + 8*96 + 48);
    b45_tm_w8(br + 16, br + 16 + 48, kr + 16, kr + 16 + 48, tr + 16*96, tr + 16*96 + 48);
    b45_tm_w8(br + 24, br + 24 + 48, kr + 24, kr + 24 + 48, tr + 24*96, tr + 24*96 + 48);
    b45_tm_w8(br + 32, br + 32 + 48, kr + 32, kr + 32 + 48, tr + 32*96, tr + 32*96 + 48);
    b45_tm_w8(br + 40, br + 40 + 48, kr + 40, kr + 40 + 48, tr + 40*96, tr + 40*96 + 48);
}
static void b45_t2_plane(double*restrict br, double*restrict tr){
    b45_t_w8(tr + 0, tr + 0 + 48, br + 0*96, br + 0*96 + 48);
    b45_t_w8(tr + 8, tr + 8 + 48, br + 8*96, br + 8*96 + 48);
    b45_t_w8(tr + 16, tr + 16 + 48, br + 16*96, br + 16*96 + 48);
    b45_t_w8(tr + 24, tr + 24 + 48, br + 24*96, br + 24*96 + 48);
    b45_t_w8(tr + 32, tr + 32 + 48, br + 32*96, br + 32*96 + 48);
    b45_t_w8(tr + 40, tr + 40 + 48, br + 40*96, br + 40*96 + 48);
}
static void b45_xslice(double*restrict xr, long j1){
  long off = j1*96;
      b45_xp_w8(xr + off + 0, xr + off + 0 + 48);
      b45_xp_w8(xr + off + 8, xr + off + 8 + 48);
      b45_xp_w8(xr + off + 16, xr + off + 16 + 48);
      b45_xp_w8(xr + off + 24, xr + off + 24 + 48);
      b45_xp_w8(xr + off + 32, xr + off + 32 + 48);
      b45_xp_w8(xr + off + 40, xr + off + 40 + 48);
}
static void b45_stepf(double*restrict xr, double*restrict tr){
  for(long j0=0;j0<45;++j0){
    b45_t1_plane(xr + j0*4616, tr);
    b45_t2_plane(xr + j0*4616, tr);
  }
  for(long j1=0;j1<45;++j1) b45_xslice(xr, j1);
}
/* interleave X-phase of volume A (already transformed this step) with the
   T-phase (step `tkind`: 0=plain first-step, 1=map-fused) of volume B.
   Uses two scratch planes so T1(q) can run while T2(q-1) drains. */
static void b45_XT(double*restrict xa,
                    double*restrict xb, const double*restrict cb,
                    double*restrict trA, double*restrict trB, int tmap){
  /* q = 0: X slice 0 + T1(plane 0) -> trA */
  b45_xslice(xa, 0);
  if(tmap) b45_t1m_plane(xb, cb, trA); else b45_t1_plane(xb, trA);
  for(long q=1;q<45;++q){
    b45_xslice(xa, q);
    b45_t2_plane(xb + (q-1)*4616, trA);
    if(tmap) b45_t1m_plane(xb + q*4616, cb + q*4616, trB);
    else     b45_t1_plane(xb + q*4616, trB);
    double* sw = trA; trA = trB; trB = sw;
  }
  b45_t2_plane(xb + (45-1)*4616, trA);
}
static void b45_stepr(double*restrict xr, const double*restrict cx, double*restrict tr, double*restrict tr_unused){
  (void)tr_unused;
  for(long j0=0;j0<45;++j0){
    b45_t1m_plane(xr + j0*4616, cx + j0*4616, tr);
    b45_t2_plane(xr + j0*4616, tr);
  }
  for(long j1=0;j1<45;++j1) b45_xslice(xr, j1);
}
static void b45_emitmc(const double*restrict dx, const double*restrict cx, double*restrict dst){
  double tbr[8], tbi[8];
  for(long j0=0;j0<45;++j0) for(long j1=0;j1<45;++j1){
    double* s = dst + (j0*45+j1)*90;
    const double* pr = dx + j0*4616 + pos45[j1]*96;
    const double* pi = pr + 48;
    const double* qr = cx + j0*4616 + pos45[j1]*96;
    const double* qi = qr + 48;
    for(long zb=0; zb*8<45; ++zb){
      long z0 = zb*8;
      v8df zr = *(const v8df*)(pr + z0) + *(const v8df*)(qr + z0);
      v8df zi = *(const v8df*)(pi + z0) + *(const v8df*)(qi + z0);
      v8df mm = zr*zr + zi*zi;
      v8df uu = rsq8(mm);
      v8df wr_ = zr*uu, wi_ = zi*uu;
      v8df vv = rpc8(uu);
      *(v8df*)(tbr) = wr_*vv; *(v8df*)(tbi) = wi_*vv;
      long lim = 45 - z0; if(lim>8) lim=8;
      for(long q=0;q<lim;++q){ long z = z0+q; long zi2 = 0;
        // find logical z for storage position z0+q: positions are permuted, use inverse below
        (void)zi2;
        s[2*invpos45[z]] = tbr[q]; s[2*invpos45[z]+1] = tbi[q];
      }
    }
  }
}
static void b45_Tphase(double*restrict xr, const double*restrict cx, double*restrict tr, int tmap){
  for(long j0=0;j0<45;++j0){
    if(tmap) b45_t1m_plane(xr + j0*4616, cx + j0*4616, tr);
    else     b45_t1_plane(xr + j0*4616, tr);
    b45_t2_plane(xr + j0*4616, tr);
  }
}
static void run45_one(long m, const double* x0, const double* c, double* out1, double* outm){
  b45_conv_in(x0, B45_x, 1.0);
  b45_conv_in(c,  B45_c, 0.0);
  b45_stepf(B45_x, B45_t);
  b45_emitmc(B45_x, B45_c, out1);
  for(long it=2; it<=m; ++it)
    b45_stepr(B45_x, B45_c, B45_t, B45_t2);
  b45_emitmc(B45_x, B45_c, outm);
}
static void run45_pair(long m, const double* x0, const double* c, double* out1, double* outm){
  double *xa = B45_x, *ca = B45_c, *xb = B45_xb, *cb = B45_cb;
  const long VN = (long)182250;
  b45_conv_in(x0,      xa, 1.0);
  b45_conv_in(c,       ca, 0.0);
  b45_conv_in(x0 + VN, xb, 1.0);
  b45_conv_in(c  + VN, cb, 0.0);
  b45_Tphase(xa, ca, B45_t, 0);
  for(long it=1; it<=m; ++it){
    b45_XT(xa, xb, cb, B45_t, B45_t2, it>=2);
    if(it==1) b45_emitmc(xa, ca, out1);
    if(it<m){
      b45_XT(xb, xa, ca, B45_t, B45_t2, 1);
    } else {
      for(long j1=0;j1<45;++j1) b45_xslice(xb, j1);
    }
    if(it==1) b45_emitmc(xb, cb, out1 + VN);
  }
  b45_emitmc(xa, ca, outm);
  b45_emitmc(xb, cb, outm + VN);
}
static void run45(long B, long m, const double* x0, const double* c, double* out1, double* outm){
  b45_init();
  long b = 0;
  if(0){ /* pairwise interleave: no gain measured (shared L3 bottleneck) */
    for(; b+2<=B; b+=2)
      run45_pair(m, x0 + b*(long)182250, c + b*(long)182250, out1 + b*(long)182250, outm + b*(long)182250);
  }
  for(; b<B; ++b)
    run45_one(m, x0 + b*(long)182250, c + b*(long)182250, out1 + b*(long)182250, outm + b*(long)182250);
}
